 // keptBaselineRefusals are the refusals of kept steps that are red, or never run because an
 // earlier step failed, in both unchanged-tree observations. They state a claim about current
 // behaviour that the run itself disproves or leaves unobserved, so no reviewer verdict clears them.
+// Blocked steps of one scenario, property and failure text share one refusal that lists their lines.
 func keptBaselineRefusals(first, second map[string]keptStepState, props []propertyReport) []string {
 	var out []string
+	type blockedGroup struct {
+		name, scenario, detail string
+		lines                  []int
+	}
+	groups := map[string]*blockedGroup{}
 	for key, a := range first {
 		b, ok := second[key]
 		if !ok || a.red != b.red {
@@ -70,10 +76,33 @@
 		}
 		if a.red {
 			out = append(out, fmt.Sprintf("- %s (kept) | scenario %q line %d asserts unchanged behaviour but is red on the unchanged tree in both observations: %s. Fix the expected value to what the unchanged code returns, or mark the behaviour as changed in the Intent. Resubmitting unchanged is refused again.", name, a.scenario, a.line, b.detail))
-		} else {
-			out = append(out, fmt.Sprintf("- %s (kept) | scenario %q line %d is meant to assert unchanged behaviour but never runs on the unchanged tree: an earlier step of the scenario fails on new behaviour (%s). Assert the unchanged behaviour in a step that runs on the baseline, such as its own scenario. Resubmitting unchanged is refused again.", name, a.scenario, a.line, b.detail))
+			continue
 		}
+		gk := strings.Join([]string{name, a.scenario, b.detail}, "\x00")
+		g := groups[gk]
+		if g == nil {
+			g = &blockedGroup{name: name, scenario: a.scenario, detail: b.detail}
+			groups[gk] = g
+		}
+		g.lines = append(g.lines, a.line)
+	}
+	for _, g := range groups {
+		slices.Sort(g.lines)
+		out = append(out, fmt.Sprintf("- %s (kept) | scenario %q %s is meant to assert unchanged behaviour but never runs on the unchanged tree: an earlier step of the scenario fails on new behaviour (%s). Assert the unchanged behaviour in a step that runs on the baseline, such as its own scenario. Resubmitting unchanged is refused again.", g.name, g.scenario, keptLinesLabel(g.lines), g.detail))
 	}
 	slices.Sort(out)
 	return out
 }
+
+// keptLinesLabel names the feature lines of blocked kept steps: "line 5" for one, "lines 3, 4 and 5" for
+// several, in ascending order.
+func keptLinesLabel(lines []int) string {
+	if len(lines) == 1 {
+		return fmt.Sprintf("line %d", lines[0])
+	}
+	parts := make([]string, len(lines))
+	for i, l := range lines {
+		parts[i] = fmt.Sprint(l)
+	}
+	return "lines " + strings.Join(parts[:len(parts)-1], ", ") + " and " + parts[len(parts)-1]
+}

